Row(
    Modifier.fillMaxWidth().padding(16.dp),
    verticalAlignment = Alignment.CenterVertically,
    horizontalArrangement = Arrangement.spacedBy(12.dp),
) {
    Icon(Icons.Default.Description, contentDescription = null)
    Column(Modifier.weight(1f)) { Text(note.title); Text(note.preview) }
    IconButton(onClick = onStar) { Icon(Icons.Default.Star, "Star note") }
}

BoxWithConstraints {
    if (maxWidth < 600.dp) NoteList(notes)
    else Row { NoteList(notes, Modifier.weight(1f)); NoteDetail(selected, Modifier.weight(1f)) }
}
